// ===== Функция отрисовки первого экрана (адаптирована) =====
static void draw_screen_1(gfx_canvas_t *canvas) {
    // Заливка фона
    gfx_canvas_fill(canvas, 0xD809);

    // Верхняя линия
    gfx_canvas_draw_line(canvas, -1, 13, 319, 13, GFX_WHITE);

    // Нижняя линия
    gfx_canvas_draw_line(canvas, 319, 218, 0, 218, GFX_WHITE);

    // Монохромный битмап
    gfx_canvas_draw_bitmap_mono(canvas, 58, -4,
                                image_982f4ed7d64cf132d2647654eb5dff37_bits,
                                320, 240, GFX_WHITE);
}

// ===== Задача UI =====
void ui_task(void *arg) {
    // 1. Создаём canvas нужного размера (альбомная ориентация 320x240)
    gfx_canvas_t canvas;
    if (gfx_canvas_init(&canvas, 320, 240) != ESP_OK) {
        // Если память не выделилась — критическая ошибка, но мы хотя бы сообщим
        printf("UI: failed to allocate canvas\n");
        vTaskDelete(NULL);
        return;
    }
    gfx_canvas_fill(&canvas, GFX_BLACK);
gfx_canvas_fill_rect(&canvas, 0, 100, 320, 20, GFX_WHITE);  // y=100, высота 20px
gfx_canvas_flush(&canvas);
vTaskDelay(pdMS_TO_TICKS(2000));

    // 2. Рисуем статичный экран один раз
    draw_screen_1(&canvas);

    // 3. Отправляем на дисплей
    gfx_canvas_flush(&canvas);

    // 4. Основной цикл — здесь будем обрабатывать обновления
    while (1) {
        // Пока ничего не делаем, просто ждём.
        // В будущем: читаем очереди, рисуем динамические элементы,
        // затем снова gfx_canvas_flush().
        vTaskDelay(pdMS_TO_TICKS(50)); // 20 fps минимум
    }

    // Сюда не дойдём, но на всякий случай
    gfx_canvas_deinit(&canvas);
    vTaskDelete(NULL);
}
